// Package straceparser parses ONE LINE of `strace -f --quiet=attach -y -s 4096`
// output into a syntax tree, with the repo's grammar-driven parser.
//
// The structure is not written here.  It is in
//
//	code/grammars/strace/strace.grammar
//
// (compiled data in grammar_data.go, generated by `grammar-tools
// compile-grammar`), over the tokens of strace.tokens (package
// strace-lexer).  This package compiles the grammar ONCE at start-up and adds
// what a grammar file cannot say: the line-level checks and the mapping from a
// parse failure to a typed error.
//
// # Syntax only
//
// The tree says WHICH SHAPE a line has (call, interrupted call, resumed half,
// exit, signal, killed-at-entry) and where the arguments are.  It does not
// interpret arguments or results, and it knows nothing about refusal reasons.
// A consumer switches on the tree's body rule and reads raw text by token
// columns.
//
// # Fail closed
//
// There is no error recovery.  ParseLine either returns a complete tree or an
// error, and the error is a *LineError that says which kind of failure it was,
// so the consumer can choose its own reason.  Resource limits (nesting depth,
// token count, memo size) are in Options; the limit errors are KindLimit.
package straceparser

import (
	"errors"
	"strings"

	"github.com/adhithyan15/coding-adventures/code/packages/go/lexer"
	"github.com/adhithyan15/coding-adventures/code/packages/go/parser"
	stracelexer "github.com/adhithyan15/coding-adventures/code/packages/go/strace-lexer"
)

// StartRule is the grammar rule a line is parsed from.
const StartRule = "line"

// Limits a consumer is expected to run with (KILN04 section 4.9).
const (
	// MaxBracketNesting is the deepest bracket nesting a line may have
	// (a nested call counts as a bracket): 64.
	MaxBracketNesting = 64
	// DefaultMaxDepth is the parser's MaxDepth for that.  It counts RULE
	// levels, and each bracket level costs two (group and inner) on top of 8
	// for the line itself.  A test pins that exactly MaxBracketNesting levels
	// parse and one more is refused, so a grammar edit that changes the cost
	// is caught.
	DefaultMaxDepth = 2*MaxBracketNesting + 8
	// DefaultMaxTokens bounds the tokens of one line.
	DefaultMaxTokens = 65536
)

// compiled is the grammar, compiled once.  An error would be a bug in the
// committed grammar data; it is kept and returned, and a test asserts nil.
var compiled, compileErr = parser.CompileGrammar(ParserGrammarData)

// Compiled returns the compiled parser grammar (shared, immutable), so a
// consumer can inspect it or call Parse itself.
func Compiled() (*parser.Compiled, error) { return compiled, compileErr }

// Options configures ParseLine.  It embeds the shared parser's Options (depth,
// token and memo limits, start rule) and adds the line-level ones.  EVERY zero
// limit is filled from DefaultOptions individually, so setting one field never
// leaves another unlimited.
type Options struct {
	parser.Options

	// MaxLineBytes is the longest line accepted, checked before lexing.
	// Zero means DefaultMaxLineBytes (1 MiB).
	MaxLineBytes int

	// LenientQuoted turns OFF the strict decoding of every quoted string.
	// By default a quoted string with a bad escape (\q, \400, \x4, a trailing
	// backslash) refuses the line, as an annotation with one does.
	LenientQuoted bool
}

// DefaultOptions returns the limits the consumer should run with: bracket
// nesting 64, 65,536 tokens, a memo bound of rules times tokens (the most the
// packrat memo can ever need) and 1 MiB per line.
func DefaultOptions() Options {
	return Options{
		Options: parser.Options{
			MaxDepth:     DefaultMaxDepth,
			MaxTokens:    DefaultMaxTokens,
			MaxMemoSlots: memoFor(DefaultMaxTokens),
			StartRule:    StartRule,
		},
		MaxLineBytes: stracelexer.DefaultMaxLineBytes,
	}
}

func memoFor(tokens int) int { return len(ParserGrammarData.Rules) * (tokens + 1) }

// withDefaults fills each zero limit from DefaultOptions.  A memo bound that was
// left zero follows the token cap actually in force, so it is never looser than
// needed.
func (o Options) withDefaults() Options {
	if o.MaxDepth <= 0 {
		o.MaxDepth = DefaultMaxDepth
	}
	if o.MaxTokens <= 0 {
		o.MaxTokens = DefaultMaxTokens
	}
	if o.MaxMemoSlots <= 0 {
		o.MaxMemoSlots = memoFor(o.MaxTokens)
	}
	if o.MaxLineBytes <= 0 {
		o.MaxLineBytes = stracelexer.DefaultMaxLineBytes
	}
	if o.StartRule == "" {
		o.StartRule = StartRule
	}
	return o
}

// Kind classifies a parse failure.
type Kind int

const (
	// KindSyntax: the tokens do not form a line of the grammar.
	KindSyntax Kind = iota
	// KindErrToken: the first thing wrong is an ERR_* token (an unterminated
	// quote or annotation, a bad "<", a bad resume marker, a control
	// character).  LineError.Token is that token.
	KindErrToken
	// KindBadAnnotation: an annotation (word<...>) whose escapes do not decode
	// strictly.  LineError.Token is the ANNOTATED token.
	KindBadAnnotation
	// KindSpace: the line starts or ends with a space.
	KindSpace
	// KindNewline: the line contains a newline.
	KindNewline
	// KindLimit: a resource limit (line bytes, depth, tokens, memo) was exceeded.
	KindLimit
	// KindBadQuoted: a quoted string whose escapes do not decode strictly.
	// LineError.Token is the QUOTED token.
	KindBadQuoted
)

// LineError is the error of ParseLine and ParseLineTokens.
type LineError struct {
	Kind  Kind
	Token lexer.Token // the offending token (KindSyntax, KindErrToken, KindBadAnnotation)
	Err   error       // the underlying error, if any
	Msg   string
}

func (e *LineError) Error() string {
	if e.Err != nil {
		return "strace line: " + e.Msg + ": " + e.Err.Error()
	}
	return "strace line: " + e.Msg
}

// Unwrap exposes the cause, so errors.Is(err, parser.ErrMaxDepth) works.
func (e *LineError) Unwrap() error { return e.Err }

// Ambiguous reports whether the failure is of the kind the old hand-written
// scanner called an ambiguous path: a bad annotation (KindBadAnnotation), or an
// ERR_ANNOT_* token that stracelexer.Ambiguous says is one.
func (e *LineError) Ambiguous() bool {
	switch e.Kind {
	case KindBadAnnotation, KindBadQuoted:
		return true
	case KindErrToken:
		return stracelexer.Ambiguous(e.Token)
	}
	return false
}

// ParseLine tokenizes and parses one line.  Every zero limit in opts is filled
// from DefaultOptions.
func ParseLine(line string, opts Options) (*parser.ASTNode, error) {
	ast, _, err := ParseLineTokens(line, opts)
	return ast, err
}

// ParseLineTokens is ParseLine that also returns the tokens, which carry the
// Columns a consumer needs to cut raw text out of the line.
//
// Besides the grammar it enforces what the grammar cannot see:
//
//   - the byte limit, before any lexing;
//   - no newline in the line (the parser would silently skip a NEWLINE token);
//   - no leading space and no trailing space (the lexer skips spaces, so the
//     grammar cannot see them).  A leading space is refused by the old scanner
//     too; a trailing space was accepted after a call's result, so refusing it
//     is a documented stricter-only divergence (D24 table);
//   - every annotation, and (unless Options.LenientQuoted) every quoted string,
//     decodes strictly (the lexer delimits them leniently; see ANNOTATED and
//     QUOTED in strace.tokens).
//
// An ERR_* token or a bad annotation or string anywhere in the line is reported
// ahead of a syntax error (see the loop below).
//
// A decoded string is arbitrary bytes (it can hold NUL and invalid UTF-8): a
// consumer that uses one as a path must reject NUL and invalid UTF-8 itself.
func ParseLineTokens(line string, opts Options) (*parser.ASTNode, []lexer.Token, error) {
	opts = opts.withDefaults()
	toks, err := checkLine(line, opts)
	if err != nil {
		return nil, toks, err
	}
	ast, perr := compiled.Parse(toks, opts.Options)
	if perr == nil {
		return ast, toks, nil
	}
	return nil, toks, classifyParseError(perr)
}

// checkLine is everything ParseLineTokens does before the parse: the
// line-level checks, the lexing and the scan for the first token the grammar can
// never accept.  opts must already have withDefaults applied.  It returns the
// tokens (also alongside an error, where there are any) and a *LineError, or nil.
// The compact path (ParseLineInto) calls it too, so both paths refuse the same
// lines with the same error values by construction.
func checkLine(line string, opts Options) ([]lexer.Token, error) {
	toks, _, err := checkLineWithScratch(line, opts, nil, false)
	return toks, err
}

// checkLineWithScratch is checkLine's shared validation path. When reuse is
// true, only a parser-owned token slice is supplied to TokenizeLineMaxInto;
// hook-bearing callers stay on the owning path so hooks may retain or replace
// their input without observing later mutation.
func checkLineWithScratch(line string, opts Options, dst []lexer.Token, reuse bool) ([]lexer.Token, []lexer.Token, error) {
	scratch := dst[:0]
	if compileErr != nil {
		return nil, scratch, &LineError{Kind: KindSyntax, Err: compileErr, Msg: "grammar did not compile"}
	}
	if len(line) > opts.MaxLineBytes {
		return nil, scratch, &LineError{Kind: KindLimit, Err: stracelexer.ErrLineTooLong, Msg: "line too long"}
	}
	if strings.IndexByte(line, '\n') >= 0 {
		return nil, scratch, &LineError{Kind: KindNewline, Err: stracelexer.ErrNewline, Msg: "newline in line"}
	}
	if line != "" && (line[0] == ' ' || line[len(line)-1] == ' ') {
		return nil, scratch, &LineError{Kind: KindSpace, Msg: "line starts or ends with a space"}
	}
	var toks []lexer.Token
	var err error
	if reuse {
		toks, err = stracelexer.TokenizeLineMaxInto(line, opts.MaxLineBytes, dst)
	} else {
		toks, err = stracelexer.TokenizeLineMax(line, opts.MaxLineBytes)
	}
	if err != nil {
		return nil, scratch, &LineError{Kind: KindSyntax, Err: err, Msg: "lexing"}
	}
	if reuse {
		scratch = toks
	}
	if len(toks) > opts.MaxTokens {
		return toks, scratch, &LineError{Kind: KindLimit, Err: parser.ErrMaxTokens, Msg: "too many tokens"}
	}

	// The first thing in the line that the grammar can never accept: an ERR_*
	// token, or an annotation or string that does not decode strictly (only a
	// body with a backslash can fail; the lexer already excluded raw "<", ">"
	// and controls, so a common one costs one IndexByte).  Any of them refuses
	// the line, so the parse is skipped: hostile input is refused at the cost of
	// one pass.
	//
	// The parser reports WHERE a structural failure happened only as the start
	// of the rule that failed, so a syntax error cannot be ordered against a
	// later bad token.  The bad token wins; the two differ only in the reason a
	// consumer picks (a documented reason-only divergence).
	for i := range toks {
		t := toks[i]
		switch {
		case stracelexer.IsErrToken(t):
			return toks, scratch, &LineError{Kind: KindErrToken, Token: t, Msg: "bad " + t.TypeName}
		case t.TypeName == "ANNOTATED" && strings.IndexByte(t.Value, '\\') >= 0:
			_, body := stracelexer.AnnotationBody(t)
			if _, derr := stracelexer.DecodeAnnotation(body); derr != nil {
				return toks, scratch, &LineError{Kind: KindBadAnnotation, Token: t, Err: derr, Msg: "annotation does not decode"}
			}
		case t.TypeName == "QUOTED" && !opts.LenientQuoted && strings.IndexByte(t.Value, '\\') >= 0:
			body, _ := stracelexer.QuotedBody(t)
			if _, derr := stracelexer.DecodeString(body); derr != nil {
				return toks, scratch, &LineError{Kind: KindBadQuoted, Token: t, Err: derr, Msg: "string does not decode"}
			}
		}
	}
	return toks, scratch, nil
}

// classifyParseError maps an error of the shared parser to a *LineError.
func classifyParseError(perr error) error {
	var gerr *parser.GrammarParseError
	tok := lexer.Token{}
	if errors.As(perr, &gerr) {
		tok = gerr.Tok
	}
	if errors.Is(perr, parser.ErrMaxDepth) || errors.Is(perr, parser.ErrMaxTokens) || errors.Is(perr, parser.ErrMaxMemoSlots) {
		return &LineError{Kind: KindLimit, Err: perr, Msg: "limit exceeded"}
	}
	return &LineError{Kind: KindSyntax, Token: tok, Err: perr, Msg: "syntax"}
}

// Body returns the body node of a parsed line: the child of the `line` rule
// after the pid, one of call_line, resumed_line, exit_line, signal_line,
// dead_line, dead_resumed_line.
func Body(ast *parser.ASTNode) *parser.ASTNode {
	if ast == nil || ast.RuleName != StartRule {
		return nil
	}
	for _, c := range ast.Children {
		if n, ok := c.(*parser.ASTNode); ok && n.RuleName == "body" {
			for _, cc := range n.Children {
				if b, ok := cc.(*parser.ASTNode); ok {
					return b
				}
			}
		}
	}
	return nil
}
